  "tools.atomic": {
    "file": "src/minidsh/tools.py",
    "start": 205,
    "code": "def atomic_write(path: Path, content: str) -> None:\n    path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.parent / f\".{path.name}.{uuid.uuid4().hex}.minidsh.tmp\"\n    try:\n        temporary.write_text(content, encoding=\"utf-8\")\n        os.replace(temporary, path)\n    finally:\n        if temporary.exists():\n            temporary.unlink()"
  },
  "deepseek.sse": {
    "file": "src/minidsh/deepseek.py",
    "start": 281,
    "code": "def iter_sse(response: object, cancel_token: Optional[CancellationToken] = None) -> Iterator[Dict[str, object]]:\n    event_name: Optional[str] = None\n    data_lines: List[str] = []\n    for raw_line in response:  # type: ignore[attr-defined]\n        if cancel_token is not None:\n            cancel_token.throw_if_cancelled()\n        line = raw_line.decode(\"utf-8\").rstrip(\"\\r\\n\")\n        if not line:\n            if not data_lines:\n                event_name = None\n                continue\n            data = \"\\n\".join(data_lines)\n            try:\n                event = json.loads(data)\n            except json.JSONDecodeError as exc:\n                raise LlmError(\"DeepSeek Messages SSE contains invalid JSON\", \"MALFORMED_RESPONSE\") from exc\n            if not isinstance(event, dict) or not isinstance(event.get(\"type\"), str):\n                raise LlmError(\"DeepSeek Messages SSE event is missing its type\", \"MALFORMED_RESPONSE\")\n            if event_name is not None and event_name != event[\"type\"]:\n                raise LlmError(\"DeepSeek Messages SSE event type mismatch\", \"MALFORMED_RESPONSE\")\n            yield event\n            event_name = None\n            data_lines = []\n            continue\n        if line.startswith(\":\"):\n            continue\n        if line.startswith(\"event:\"):\n            event_name = line[6:].strip()\n        elif line.startswith(\"data:\"):\n            data_lines.append(line[5:].lstrip())\n    if data_lines:\n        raise LlmError(\"DeepSeek Messages SSE ended with an incomplete event\", \"STREAM_CLOSED\")"
  },
